6	 */
7	
8	/*
9	 * Copy-first port of
10	 * node_modules/@salesforce/retail-react-app/app/pages/product-detail/index.jsx
11	 * (retail-react-app 10.0.0), converted to TypeScript per AGENTS.md's copy-first rule.
12	 *
13	 * The differences from the base file are the TypeScript annotations below, house
14	 * formatting, a small number of optional-chaining guards that strictNullChecks
15	 * requires — each flagged in place with a `Deviation from the base file` comment —
16	 * the relative `product-view` import, which is deliberate and explained at its
17	 * import site below, and SFCC-89's static product information: a `renderHeader`
18	 * implementation that replaces the base header's title/price block with the
19	 * Zimmermann content group, plus the meta block rendered below the accordions.
20	 * Both are marked `SFCC-89` in place.
21	 */
22	
23	import React, { Fragment, useCallback, useEffect, useMemo, useRef, useState } from 'react';
24	import { Helmet } from 'react-helmet';
25	import { FormattedMessage, useIntl } from 'react-intl';
26	import { getUpdateBundleChildArray } from '@salesforce/retail-react-app/app/utils/product-utils';
27	
28	// Components
29	import { Box, Button, Stack, Heading } from '@salesforce/retail-react-app/app/components/shared/ui';
30	import {
31	  useProduct,
32	  useProducts,
33	  useCategory,
34	  useShopperCustomersMutation,
35	  useShopperBasketsV2Mutation as useShopperBasketsMutation,
36	  useCustomerId,
37	  useShopperBasketsV2MutationHelper as useShopperBasketsMutationHelper,
38	} from '@salesforce/commerce-sdk-react';
39	
40	// Hooks
41	import { useCurrentBasket } from '@salesforce/retail-react-app/app/hooks/use-current-basket';
42	import { useVariant } from '@salesforce/retail-react-app/app/hooks';
43	import useNavigation from '@salesforce/retail-react-app/app/hooks/use-navigation';
44	import useEinstein from '@salesforce/retail-react-app/app/hooks/use-einstein';
45	import useDataCloud from '@salesforce/retail-react-app/app/hooks/use-datacloud';
46	import useActiveData from '@salesforce/retail-react-app/app/hooks/use-active-data';
47	import { useServerContext } from '@salesforce/pwa-kit-react-sdk/ssr/universal/hooks';
48	import usePickupShipment from '@salesforce/retail-react-app/app/hooks/use-pickup-shipment';
49	import { useSelectedStore } from '@salesforce/retail-react-app/app/hooks/use-selected-store';
50	import { useMultiship } from '@salesforce/retail-react-app/app/hooks/use-multiship';
51	import { STORE_LOCATOR_IS_ENABLED } from '@salesforce/retail-react-app/app/constants';
52	import { getConfig } from '@salesforce/pwa-kit-runtime/utils/ssr-config';
53	// Project Components
54	import RecommendedProducts from '@salesforce/retail-react-app/app/components/recommended-products';
55	/*
56	 * Relative, not `@salesforce/retail-react-app/app/components/product-view`. The overrides
57	 * resolver (pwa-kit-dev's OverridesResolverPlugin) deliberately skips any request whose
58	 * issuer already lives in `overrides/` — see its `isFromExtends` guard — so a base-path
59	 * import from this file resolves to the *base* component even in the real app build, not
60	 * just in Storybook/Vitest. Base callers (cart, wishlist, bonus-product) still reach our
61	 * override, because their issuer is inside node_modules and so is redirected normally.
62	 */
63	import ProductView from '../../components/product-view';
64	import type { ChildProductOrderability, ProductViewRefScope } from '../../components/product-view';
65	
66	// SFCC-89 — static product information.
67	import { ZimmProductMeta } from '../../components/ui-kits/molecules/zimmProductMeta';
68	import { selectPdpProductInfo } from './productInfo';
69	import { selectVariantScopedPriceData } from './variantScopedPrice';
70	import { StaticProductHeader } from './partials/staticProductHeader';
71	import InformationAccordion from '@salesforce/retail-react-app/app/pages/product-detail/partials/information-accordion';
72	import Island from '@salesforce/retail-react-app/app/components/island';
73	
74	// SFCC-91 — PDP colour swatches.
75	import { ZimmColourSwatchGroup } from '../../components/ui-kits/molecules/zimmColourSwatchGroup';
76	
77	import { HTTPNotFound, HTTPError } from '@salesforce/pwa-kit-react-sdk/ssr/universal/errors';
78	import logger from '@salesforce/retail-react-app/app/utils/logger-instance';
79	
80	// constant
81	import {
82	  API_ERROR_MESSAGE,
83	  EINSTEIN_RECOMMENDERS,
84	  MAX_CACHE_AGE,
85	  TOAST_ACTION_VIEW_WISHLIST,
86	  TOAST_MESSAGE_ADDED_TO_WISHLIST,
87	  TOAST_MESSAGE_ALREADY_IN_WISHLIST,
88	  STALE_WHILE_REVALIDATE,
89	} from '@salesforce/retail-react-app/app/constants';
90	import { rebuildPathWithParams } from '@salesforce/retail-react-app/app/utils/url';
91	import { useHistory, useLocation, useParams } from 'react-router-dom';
92	import { useToast } from '@salesforce/retail-react-app/app/hooks/use-toast';
93	import { useWishList } from '@salesforce/retail-react-app/app/hooks/use-wish-list';
94	import { useStoreLocatorModal } from '@salesforce/retail-react-app/app/hooks/use-store-locator';
95	import { isPickupMethod } from '@salesforce/retail-react-app/app/utils/shipment-utils';
96	import { useProductInventory } from '@salesforce/retail-react-app/app/hooks/use-product-inventory';
97	
98	/*
99	 * `@salesforce/retail-react-app` ships no TypeScript types (see
100	 * overrides/app/types/vendor.d.ts, which falls back to an untyped catch-all for its
101	 * subpaths), so the product / variant / category values this page threads between base
102	 * hooks and base components have no compile-time shape *from that package*. But the shapes
103	 * themselves are `commerce-sdk-isomorphic`'s, and it does export them as
104	 * `ShopperProductsTypes.Product` / `.Variant` / `.Category` — so these aliases are a
105	 * deliberate temporary gap, not proof that no type is available, and AGENTS.md's Type
106	 * Definitions rule says to import those directly. Deferred to a follow-up only because the
107	 * substitution also clears three `no-explicit-any` warnings, moving a lint count this branch
108	 * holds as an invariant. See the same note in `components/product-view/index.tsx`.
109	 */
110	type SfccProduct = any;
111	type SfccVariant = any;
112	type SfccCategory = any;
113	
114	/*
115	 * `@salesforce/commerce-sdk-react` types its query/mutation `parameters` more narrowly than
116	 * the base JS page satisfies (it types several always-present values as optional, and takes
117	 * `ids` as an array where the base joins them itself). The casts marked "SDK param widening"
118	 * below exist only to reconcile that; each passes exactly the value the base file passes, so
119	 * none of them changes runtime behaviour.
120	 */
121	
122	/** A basket line item as this page assembles it before handing it to the baskets API. */
123	type BasketLineItem = {
124	  productId?: string;
125	  id?: string;
126	  price?: number;
127	  quantity?: number;
128	  inventoryId?: string;
129	  shipmentId?: string;
130	  bundledProductItems?: Array<{ productId?: string; quantity?: number }>;
131	};
132	
133	/** A child product selection within a product set or bundle. */
134	type ChildProductSelection = {
135	  product?: SfccProduct;
136	  variant?: SfccVariant;
137	  quantity?: number;
138	};
139	
140	/** The imperative handle ProductView exposes for set/bundle child validation. */
141	type ChildProductRef = {
142	  ref: HTMLDivElement | null;
143	  validateOrderability: ProductViewRefScope['validateOrderability'];
144	};
145	
146	/** One row of the array the base ProductView passes to `addToCart`. */
147	type ProductSelectionValue = {
148	  product?: SfccProduct;
149	  variant?: SfccVariant;
150	  quantity?: number;
151	};
152	
153	/**
154	 * Errors thrown by the commerce SDK carry the originating `Response`, which the base
155	 * page reads to map an API status onto an SSR-visible HTTP error.
156	 */
157	type CommerceApiError = Error & { response?: { status?: number } };
158	
159	const ProductDetail = () => {
160	  // react-intl returns already-bound methods, so destructuring them cannot unbind anything —
161	  // the rule cannot see that. `formatNumber` is SFCC-89's addition; the base file destructures
162	  // `formatMessage` alone. It feeds `formatPrice` below.
163	  // eslint-disable-next-line @typescript-eslint/unbound-method
164	  const { formatMessage, formatNumber } = useIntl();
165	  const history = useHistory();
166	  const location = useLocation();
167	  const einstein = useEinstein();
168	  const dataCloud = useDataCloud();
169	  const activeData = useActiveData();
170	  const toast = useToast();
171	  const navigate = useNavigation();
172	  const customerId = useCustomerId();
173	  const { onOpen: onOpenStoreLocator } = useStoreLocatorModal();
174	  const multishipEnabled = getConfig()?.app?.multishipEnabled ?? true;
175	  const storeLocatorEnabled = getConfig()?.app?.storeLocatorEnabled ?? STORE_LOCATOR_IS_ENABLED;
176	
177	  /****************************** Basket *********************************/
178	  const { data: basket, isLoading: isBasketLoading } = useCurrentBasket();
179	  const { addItemToNewOrExistingBasket } = useShopperBasketsMutationHelper();
180	  const updateItemsInBasketMutation = useShopperBasketsMutation('updateItemsInBasket');
181	  const { res } = useServerContext();
182	  if (res) {
183	    res.set('Cache-Control', `s-maxage=${MAX_CACHE_AGE}, stale-while-revalidate=${STALE_WHILE_REVALIDATE}`);
184	  }
185	
186	  /*************************** Pick up in Store ********************/
187	  const { selectedStore } = useSelectedStore();
188	  const selectedInventoryId = selectedStore?.inventoryId || null;
189	
190	  const { addInventoryIdsToPickupItems, updateDefaultShipmentIfNeeded, hasPickupItems } = usePickupShipment(basket);
191	
192	  /*************************** Multiship ********************/
193	  const { getShipmentIdForItems } = useMultiship(basket);
194	
195	  /*************************** Product Detail and Category ********************/
196	  const { productId } = useParams<{ productId?: string }>();
197	  const urlParams = new URLSearchParams(location.search);
198	  // SDK param widening — this component only mounts on `/product/:productId`, so one of the
199	  // two is always present. `useParams` types every segment optional by design — see the
200	  // comment on the react-router-dom shim in overrides/app/types/vendor.d.ts.
201	  const requestedProductId = (urlParams.get('pid') || productId) as string;
202	  const {
203	    data: productResponse,
204	    isLoading: isProductLoading,
205	    isError: isProductError,
206	    error: productError,
207	  } = useProduct(
208	    {
209	      parameters: {
210	        id: requestedProductId,
211	        perPricebook: true,
212	        expand: [
213	          'availability',
214	          'promotions',
215	          'options',
216	          'images',
217	          'prices',
218	          'variations',
219	          'set_products',
220	          'bundled_products',
221	          'page_meta_tags',
222	        ],
223	        allImages: true,
224	        ...(selectedInventoryId ? { inventoryIds: selectedInventoryId } : {}),
225	      },
226	    },
227	    {
228	      // When shoppers select a different variant (and the app fetches the new data),
229	      // the old data is still rendered (and not the skeletons).
230	      //
231	      // Load-bearing for accessibility, beyond the loading behaviour it was added for. The price
232	      // carries `aria-live` (zimmProductPrice), and a live region only announces a change if the
233	      // region already existed — a region inserted together with its content is silent. Keeping
234	      // the previous data means `ZimmProductContent` (rendered by the `StaticProductHeader`
235	      // partial) never unmounts on a variant change, so the price element survives and React
236	      // mutates its text in place, which is what gets announced.
237	      // Remove this option and the region is destroyed and rebuilt on every swatch click, and the
238	      // price stops being announced (WCAG 2.2 AA 4.1.3). No gate catches that: the atom's own test
239	      // renders it directly, and axe sees a well-formed region either way.
240	      keepPreviousData: true,
241	    },
242	  );
243	
244	  // Note: Since category needs id from product detail, it can't be server side rendered atm
245	  // until we can do dependent query on server
246	  const {
247	    data: category,
248	    isError: isCategoryError,
249	    error: categoryError,
250	  } = useCategory({
251	    parameters: {
252	      // SDK param widening — `useCategory` is a no-op until the product resolves, exactly as
253	      // in the base file.
254	      id: productResponse?.primaryCategoryId as string,
255	      levels: 1,
256	    },
257	  });
258	
259	  /****************************** Sets and Bundles *********************************/
260	  const [childProductSelection, setChildProductSelection] = useState<Record<string, ChildProductSelection>>({});
261	  const [childProductOrderability, setChildProductOrderability] = useState<Record<string, ChildProductOrderability>>(
262	    {},
263	  );
264	  const [selectedBundleQuantity, setSelectedBundleQuantity] = useState(1);
265	  const childProductRefs = React.useRef<Record<string, ChildProductRef>>({});
266	  // Deviation from the base file: `?.` on `type`. The base reads `productResponse?.type.set`,
267	  // which throws if the API ever returns a product without `type` (the SDK types it optional).
268	  // The two only differ in that already-broken case.
269	  const isProductASet = productResponse?.type?.set;
270	  const isProductABundle = productResponse?.type?.bundle;
271	
272	  const childVariantIds =
273	    isProductABundle || isProductASet
274	      ? Object.keys(childProductSelection)?.map(
275	          (key) => childProductSelection[key].variant?.productId || childProductSelection[key].product?.id,
276	        )
277	      : [];
278	
279	  const { data: variantProductData } = useProducts(
280	    {
281	      parameters: {
282	        // SDK param widening — the base file joins the ids itself and the SDK forwards the
283	        // value verbatim into the query string.
284	        ids: childVariantIds.join(',') as unknown as string[],
285	        allImages: false,
286	        ...(selectedInventoryId ? { inventoryIds: selectedInventoryId } : {}),
287	        expand: ['availability', 'variations'],
288	        select: '(data.(id,inventory,inventories,master))',
289	      },
290	    },
291	    {
292	      enabled: childVariantIds.length > 0,
293	      keepPreviousData: true,
294	    },
295	  );
296	
297	  const product: SfccProduct = useProductInventory(
298	    productResponse,
299	    variantProductData,
300	    selectedInventoryId,
301	    isProductASet,
302	    isProductABundle,
303	  );
304	
305	  /**************** Error Handling ****************/
306	
307	  if (isProductError) {
308	    const errorStatus = (productError as CommerceApiError | null)?.response?.status;
309	    switch (errorStatus) {
310	      case 404:
311	        throw new HTTPNotFound('Product Not Found.');
312	      default:
313	        throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
314	    }
315	  }
316	  if (isCategoryError) {
317	    const errorStatus = (categoryError as CommerceApiError | null)?.response?.status;
318	    switch (errorStatus) {
319	      case 404:
320	        throw new HTTPNotFound('Category Not Found.');
321	      default:
322	        throw new HTTPError(errorStatus, `HTTP Error ${errorStatus} occurred.`);
323	    }
324	  }
325	
326	  const [primaryCategory, setPrimaryCategory] = useState<SfccCategory>(category);
327	  const variant = useVariant(product);
328	
329	  // SFCC-194 — Was/Now sale price.
330	  //
331	  // Two URL states need correct priceData (mirrors feature/SFCC-194_pdp-was-now-sale-price):
332	  //
333	  //   Colour-only  → ?color=JJ8UTXX           (no pid; product is still the master)
334	  //   Colour+size  → ?color=JJ8UTXX&pid=…M    (pid present; product switches to standalone
335	  //                                              variant which lacks tieredPrices reliably)
336	  //
337	  // Strategy: keep the master product's variants[] as the authoritative tieredPrices source.
338	  // Filter them by pid (exact) or colour (set) from the URL, then call getPriceData on the
339	  // scoped result. This is overridden into renderHeader so the base ProductView's own
340	  // getPriceData call (which reads the standalone variant and loses tieredPrices) is bypassed.
341	  const masterProductRef = useRef<SfccProduct | null>(null);
342	  useEffect(() => {
343	    // Guard matches exactly what the memo reads from the cache: id (for the
344	    // cachedMasterMatchesCurrent check) and variants[] (for the filter). A partial SFCC
345	    // response that satisfies type.master but lacks either field is not useful — skip it
346	    // rather than writing a cache entry that would fall through to the deep-link fallback
347	    // one guard too late.
348	    if (productResponse?.type?.master && productResponse.id && productResponse.variants?.length) {
349	      masterProductRef.current = productResponse;
350	    }
351	  }, [productResponse]);
352	
353	  const urlPid = urlParams.get('pid') ?? undefined;
354	  const urlColour = urlParams.get('color') ?? undefined;
355	  const variantScopedPriceData = useMemo(
356	    () => selectVariantScopedPriceData(product, masterProductRef.current, urlPid, urlColour),
357	    // Re-runs when the fetched product changes (standalone variant arrives) or the URL
358	    // selection changes — both are signals the displayed price must update.
359	    // masterProductRef is a ref so it is intentionally absent from deps.
360	    // eslint-disable-next-line react-hooks/exhaustive-deps
361	    [urlPid, urlColour, product],
362	  );
363	
364	  // True while keepPreviousData holds stale product data during a variant re-fetch (size
365	  // selection). The fetched product id hasn't caught up with the URL yet, so any price
366	  // derived from the old product is unreliable — suppress it entirely until the fetch
367	  // settles rather than showing a briefly-incorrect Was/Now figure.
368	  const isPriceStale = requestedProductId !== product?.id;
369	
370	  // This page uses the `primaryCategoryId` to retrieve the category data. This attribute
371	  // is only available on `master` products. Since a variation will be loaded once all the
372	  // attributes are selected (to get the correct inventory values), the category information
373	  // is overridden. This will allow us to keep the initial category around until a different
374	  // master product is loaded.
375	  useEffect(() => {
376	    if (category) {
377	      setPrimaryCategory(category);
378	    }
379	  }, [category]);
380	
381	  /**************** Product Variant ****************/
382	  useEffect(() => {
383	    if (!variant) {
384	      return;
385	    }
386	    // update the variation attributes parameter on
387	    // the url accordingly as the variant changes
388	    const updatedUrl = rebuildPathWithParams(`${location.pathname}${location.search}`, {
389	      pid: variant?.productId,
390	    });
391	    history.replace(updatedUrl);
392	  }, [variant]);
393	
394	  /**************** Wishlist ****************/
395	  const { data: wishlist, isLoading: isWishlistLoading } = useWishList();
396	  const createCustomerProductListItem = useShopperCustomersMutation('createCustomerProductListItem');
397	
398	  const handleAddToWishlist = (product: SfccProduct, variant: SfccVariant, quantity: number) => {
399	    const isItemInWishlist = wishlist?.customerProductListItems?.find(
400	      (i: { productId?: string }) => i.productId === variant?.productId || i.productId === product?.id,
401	    );
402	
403	    if (!isItemInWishlist) {
404	      createCustomerProductListItem.mutate(
405	        {
406	          parameters: {
407	            listId: wishlist.id,
408	            // SDK param widening — `useCustomerId` returns `string | null`; this branch is
409	            // only reachable once a wishlist has loaded, which requires a customer.
410	            customerId: customerId as string,
411	          },
412	          body: {
413	            // NOTE: API does not respect quantity, it always adds 1
414	            quantity,
415	            productId: variant?.productId || product?.id,
416	            public: false,
417	            priority: 1,
418	            type: 'product',
419	          },
420	        },
421	        {
422	          onSuccess: () => {
423	            toast({
424	              title: formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
425	              status: 'success',
426	              action: (
427	                // it would be better if we could use <Button as={Link}>
428	                // but unfortunately the Link component is not compatible
429	                // with Chakra Toast, since the ToastManager is rendered via portal
430	                // and the toast doesn't have access to intl provider, which is a
431	                // requirement of the Link component.
432	                <Button variant="link" onClick={() => navigate('/account/wishlist')}>
433	                  {formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
434	                </Button>
435	              ),
436	            });
437	          },
438	          onError: () => {
439	            showError();
440	          },
441	        },
442	      );
443	    } else {
444	      toast({
445	        title: formatMessage(TOAST_MESSAGE_ALREADY_IN_WISHLIST),
446	        status: 'info',
447	        action: (
448	          <Button variant="link" onClick={() => navigate('/account/wishlist')}>
449	            {formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
450	          </Button>
451	        ),
452	      });
453	    }
454	  };
455	
456	  /**************** Add To Cart ****************/
457	  const showToast = useToast();
458	  const showError = (errorMessage?: unknown) => {
459	    const errorText = typeof errorMessage === 'string' ? errorMessage : formatMessage(API_ERROR_MESSAGE);
460	
461	    showToast({
462	      title: errorText,
463	      status: 'error',
464	    });
465	  };
466	
467	  const [pickupInStoreMap, setPickupInStoreMap] = useState<Record<string, boolean>>({});
468	
469	  const handlePickupInStoreChange = (productId: string, checked: boolean) => {
470	    setPickupInStoreMap((prev) => ({
471	      ...prev,
472	      [productId]: checked,
473	    }));
474	  };
475	
476	  const handleAddToCart = async (productSelectionValues: ProductSelectionValue[] = []) => {
477	    try {
478	      let productItems: BasketLineItem[] = productSelectionValues.map((item) => {
479	        const { variant, quantity } = item;
480	        // Use variant if present, otherwise use the main product
481	        const prod = variant || item.product || product;
482	        return {
483	          productId: prod?.productId || prod?.id, // productId for variant, id for product
484	          price: prod?.price,
485	          quantity,
486	        };
487	      });
488	      // Add inventory IDs for pickup items using the hook helper
489	      productItems = addInventoryIdsToPickupItems(productItems, pickupInStoreMap, selectedStore);
490	      // Defensive check: This block ensures that if, for any reason, pickup is selected for a product but no store (inventoryId) is set,
491	      // we show an error. With the current UI logic, this should never be reached, but it guards against unexpected state.
492	      if (
493	        productItems.some(
494	          // Index-type assertion, not one of the "SDK param widening" casts described above:
495	          // `pickupInStoreMap` is this page's own `Record<string, boolean>` state, and
496	          // `item.productId || item.id` is `string | undefined` on `BasketLineItem`, which
497	          // TypeScript rejects as an index (TS2538). Every item here was built above from
498	          // `prod?.productId || prod?.id`, and a key that is absent reads as `undefined` —
499	          // falsy, exactly as the base file's untyped index behaves.
500	          (item) => item.inventoryId === undefined && pickupInStoreMap[(item.productId || item.id) as string],
501	        )
502	      ) {
503	        showError(
504	          formatMessage({
505	            id: 'product_view.error.no_store_selected_for_pickup',
506	            defaultMessage: 'No valid store or inventory found for pickup',
507	          }),
508	        );
509	        return;
510	      }
511	
512	      // Check if any products have pickup selected
513	      const hasAnyPickupSelected = hasPickupItems(productSelectionValues, pickupInStoreMap, product);
514	
515	      const currentShippingMethodIsPickup = isPickupMethod(basket?.shipments?.[0]?.shippingMethod);
516	      // Only perform the check if the basket exists and has at least one item
517	      if (!multishipEnabled && basket && basket.productItems?.length > 0) {
518	        if (hasAnyPickupSelected && !currentShippingMethodIsPickup) {
519	          throw new Error(
520	            formatMessage({
521	              id: 'product_view.error.select_ship_to_address',
522	              defaultMessage: "Select 'Ship to Address' to match the delivery method for the items in your cart.",
523	            }),
524	          );
525	        }
526	        if (!hasAnyPickupSelected && currentShippingMethodIsPickup) {
527	          throw new Error(
528	            formatMessage({
529	              id: 'product_view.error.select_pickup_in_store',
530	              defaultMessage: "Select 'Pick Up in Store' to match the delivery method for the items in your cart.",
531	            }),
532	          );
533	        }
534	      }
535	
536	      // Fetch and assign a suitable shipment for product items
537	      const targetShipmentId = await getShipmentIdForItems(hasAnyPickupSelected, selectedStore);
538	
539	      if (targetShipmentId) {
540	        productItems = productItems.map((item) => ({
541	          ...item,
542	          shipmentId: targetShipmentId,
543	        }));
544	      }
545	
546	      const basketResponse = await addItemToNewOrExistingBasket(productItems);
547	
548	      // Configure shipping method for default shipment based on pickup selection
549	      await updateDefaultShipmentIfNeeded(basketResponse, targetShipmentId, hasAnyPickupSelected, selectedStore);
550	
551	      const productItemsForEinstein = productSelectionValues.map(({ product, variant, quantity }) => ({
552	        product,
553	        productId: variant?.productId || product?.id,
554	        price: variant?.price || product?.price,
555	        quantity,
556	      }));
557	      einstein.sendAddToCart(productItemsForEinstein);
558	
559	      return productSelectionValues;
560	    } catch (error) {
561	      // `catch` binds `unknown` under strict mode, and a thrown non-Error has no `.message`,
562	      // so narrow instead of asserting. Behaviour is unchanged — the previous
563	      // `(error as Error).message` also yielded `undefined` for a non-Error — but this was the
564	      // only `as` in this file without the inline reason typescript.md requires.
565	      showError(error instanceof Error ? error.message : undefined);
566	    }
567	  };
568	
569	  /**************** Product Set/Bundles Handlers ****************/
570	  const handleChildProductValidation = useCallback(() => {
571	    // Run validation for all child products. This will ensure the error
572	    // messages are shown.
573	    Object.values(childProductRefs.current).forEach(({ validateOrderability }) => {
574	      validateOrderability({ scrollErrorIntoView: false });
575	    });
576	
577	    // Using ot state for which child products are selected, scroll to the first
578	    // one that isn't selected and requires a variant selection.
579	    const selectedProductIds = Object.keys(childProductSelection);
580	    const firstUnselectedProduct = product?.childProducts?.find(
581	      ({ product: childProduct }: { product: SfccProduct }) => {
582	        // Skip validation for standard products (no variations)
583	        if (childProduct.type?.item) {
584	          return false;
585	        }
586	        return !selectedProductIds.includes(childProduct.id);
587	      },
588	    )?.product;
589	
590	    if (firstUnselectedProduct) {
591	      // Get the reference to the product view and scroll to it.
592	      const { ref } = childProductRefs.current[firstUnselectedProduct.id];
593	
594	      // Deviation from the base file: `?.` on `ref`, required by strictNullChecks —
595	      // `ChildProductRef.ref` is typed `HTMLDivElement | null`. The base reads
596	      // `ref.scrollIntoView` unguarded and throws when the child view has not mounted; ours
597	      // short-circuits and returns `false`. The unguarded call inside the block is reached
598	      // only once this guard has passed.
599	      if (ref?.scrollIntoView) {
600	        ref.scrollIntoView({
601	          behavior: 'smooth',
602	          block: 'end',
603	        });
604	      }
605	
606	      return false;
607	    }
608	
609	    return true;
610	  }, [product, childProductSelection]);
611	
612	  /**************** Product Set Handlers ****************/
613	  // 1. Gather the selected child products from state.
614	  // 2. Call handleAddToCart with the selected products.
615	  // 3. The add-to-cart modal will be opened in handleAddToCart.
616	  const handleProductSetAddToCart = () => {
617	    // Get all the selected products, and pass them to the addToCart handler which
618	    // accepts an array.
619	    const productSelectionValues = Object.values(childProductSelection);
620	    return handleAddToCart(productSelectionValues);
621	  };
622	
623	  /**************** Product Bundle Handlers ****************/
624	  // Top level bundle does not have variants
625	  const handleProductBundleAddToCart = async ([{ quantity: selectedQuantity }]: Array<{ quantity?: number }>) => {
626	    try {
627	      const childProductSelections = Object.values(childProductSelection);
628	      // Check if any products have pickup selected (including main product and bundle items)
629	      const bundleSelectionValues = [{ product, variant: null, selectedQuantity }, ...childProductSelections];
630	      const hasAnyPickupSelected = hasPickupItems(bundleSelectionValues, pickupInStoreMap, product);
631	
632	      // Check for delivery method conflicts before adding to cart
633	      if (!multishipEnabled && basket && basket.productItems?.length > 0) {
634	        const currentShippingMethod = basket?.shipments?.[0]?.shippingMethod;
635	        const currentShippingMethodIsPickup = isPickupMethod(currentShippingMethod);
636	
637	        // If there's no shipping method, treat it as non-pickup (ship to address)
638	        if (hasAnyPickupSelected && (!currentShippingMethod || !currentShippingMethodIsPickup)) {
639	          throw new Error(
640	            formatMessage({
641	              id: 'product_view.error.select_ship_to_address',
642	              defaultMessage: "Select 'Ship to Address' to match the delivery method for the items in your cart.",
643	            }),
644	          );
645	        } else if (!hasAnyPickupSelected && currentShippingMethod && currentShippingMethodIsPickup) {
646	          throw new Error(
647	            formatMessage({
648	              id: 'product_view.error.select_pickup_in_store',
649	              defaultMessage: "Select 'Pick Up in Store' to match the delivery method for the items in your cart.",
650	            }),
651	          );
652	        }
653	      }
654	
655	      let productItems: BasketLineItem[] = [
656	        {
657	          productId: product.id,
658	          price: product.price,
659	          quantity: selectedQuantity,
660	          // The add item endpoint in the shopper baskets API does not respect variant selections
661	          // for bundle children, so we have to make a follow up call to update the basket
662	          // with the chosen variant selections
663	          bundledProductItems: childProductSelections.map((child) => {
664	            return {
665	              productId: child.variant?.productId || child.product?.id,
666	              quantity: child.quantity,
667	            };
668	          }),
669	        },
670	      ];
671	
672	      // Add inventory IDs for pickup items using the hook helper
673	      productItems = addInventoryIdsToPickupItems(productItems, pickupInStoreMap, selectedStore);
674	
675	      // Fetch and assign a suitable shipment for product items
676	      const targetShipmentId = await getShipmentIdForItems(hasAnyPickupSelected, selectedStore);
677	
678	      if (targetShipmentId) {
679	        productItems = productItems.map((item) => ({
680	          ...item,
681	          shipmentId: targetShipmentId,
682	        }));
683	      }
684	
685	      const res = await addItemToNewOrExistingBasket(productItems);
686	
687	      const bundleChildMasterIds = childProductSelections.map((child) => {
688	        return child.product.id;
689	      });
690	
691	      // since the returned data includes all products in basket
692	      // here we compare list of productIds in bundleProductItems of each productItem to filter out the
693	      // current bundle that was last added into cart
694	      // Deviation from the base file: `?.` on `productItems`. The SDK types it optional; the
695	      // base file assumes the just-created basket always has line items.
696	      const currentBundle = res.productItems?.find((productItem: SfccProduct) => {
697	        if (!productItem.bundledProductItems?.length) return;
698	        const bundleChildIds = productItem.bundledProductItems?.map((item: { productId?: string }) => {
699	          // seek out the bundle child that still uses masterId as product id
700	          return item.productId;
701	        });
702	        return bundleChildIds.every((id: string) => bundleChildMasterIds.includes(id));
703	      });
704	
705	      const itemsToBeUpdated = getUpdateBundleChildArray(currentBundle, childProductSelections);
706	
707	      if (itemsToBeUpdated.length) {
708	        // make a follow up call to update child variant selection for product bundle
709	        // since add item endpoint doesn't currently consider product bundle child variants
710	        await updateItemsInBasketMutation.mutateAsync({
711	          // SDK param widening — `method` is a real, honoured option on the v2 baskets
712	          // mutation (the base file relies on it to send PATCH rather than the default), but
713	          // it is absent from the published mutation-parameter type. Dropping it would change
714	          // the HTTP verb, so the argument is asserted instead.
715	          method: 'PATCH',
716	          parameters: {
717	            // `res` is the basket this call just wrote to.
718	            basketId: res.basketId as string,
719	          },
720	          body: itemsToBeUpdated,
721	        } as Parameters<typeof updateItemsInBasketMutation.mutateAsync>[0]);
722	      }
723	
724	      // Configure shipping method based on pickup selection
725	      await updateDefaultShipmentIfNeeded(res, targetShipmentId, hasAnyPickupSelected, selectedStore);
726	
727	      einstein.sendAddToCart(productItems);
728	
729	      return childProductSelections;
730	    } catch (error) {
731	      showError(error);
732	    }
733	  };
734	
735	  /**************** Einstein ****************/
736	  useEffect(() => {
737	    if (product && product.type.set) {
738	      einstein.sendViewProduct(product);
739	      dataCloud.sendViewProduct(product);
740	      const childrenProducts = product.setProducts;
741	      childrenProducts.map((child: SfccProduct) => {
742	        try {
743	          einstein.sendViewProduct(child);
744	        } catch (err) {
745	          logger.error('Einstein sendViewProduct error', {
746	            namespace: 'ProductDetail.useEffect',
747	            additionalProperties: { error: err, child },
748	          });
749	        }
750	        activeData.sendViewProduct(category, child, 'detail');
751	        dataCloud.sendViewProduct(child);
752	      });
753	    } else if (product) {
754	      try {
755	        einstein.sendViewProduct(product);
756	      } catch (err) {
757	        logger.error('Einstein sendViewProduct error', {
758	          namespace: 'ProductDetail.useEffect',
759	          additionalProperties: { error: err, product },
760	        });
761	      }
762	      activeData.sendViewProduct(category, product, 'detail');
763	      dataCloud.sendViewProduct(product);
764	    }
765	  }, [product]);
766	
767	  /**************** SFCC-89 — static product information ****************/
768	  // This formatter never executes. The page reads only `modelInfo` and `styleCode` off the mapper
769	  // — the meta block below the accordions carries no price at all (`ZimmProductMeta`'s props are
770	  // `modelInfo`/`styleCode`) — so `null` is passed for `priceData` below and the mapper's price
771	  // branch (`typeof priceData?.currentPrice === 'number'`) is always false. It exists solely to
772	  // satisfy `selectPdpProductInfo`'s required `formatPrice` parameter, which stays required so
773	  // that module can hold its own contract of being free of react-intl.
774	  //
775	  // `partials/staticProductHeader.tsx` declares an identical formatter and that one IS live. The
776	  // two cannot disagree on a rendered price, because only one of them ever formats anything.
777	  const formatPrice = (amount: number, priceCurrency: string) =>
778	    formatNumber(amount, { style: 'currency', currency: priceCurrency });
779	
780	  // Model copy and the style code are not part of the content group: the design places them at
781	  // the foot of the column, below the accordions, so the page positions them itself.
782	  const staticInfo = selectPdpProductInfo(product, null, product?.currency ?? '', formatPrice);
783	
784	  return (
785	    <Box className="sf-product-detail-page" layerStyle="page" data-testid="product-details-page">
786	      <Heading as="h1" srOnly>
787	        <FormattedMessage defaultMessage="Product Details" id="product_detail.title.product_details" />
788	      </Heading>
789	      <Helmet>
790	        <title>{product?.pageTitle}</title>
791	        {product?.pageMetaTags?.length > 0 &&
792	          product.pageMetaTags.map(({ id, value }: { id: string; value: string }) => (
793	            <meta name={id} content={value} key={id} />
794	          ))}
795	        {/* Fallback for description if not included in pageMetaTags */}
796	        {!product?.pageMetaTags?.some((tag: { id: string }) => tag.id === 'description') &&
797	          product?.pageDescription && <meta name="description" content={product.pageDescription} />}
798	      </Helmet>
799	
800	      <Stack spacing={16}>
801	        {isProductASet || isProductABundle ? (
802	          <Fragment>
803	            <Island hydrateOn={'visible'}>
804	              <ProductView
805	                product={product}
806	                category={primaryCategory?.parentCategoryTree || []}
807	                addToCart={isProductASet ? handleProductSetAddToCart : handleProductBundleAddToCart}
808	                addToWishlist={handleAddToWishlist}
809	                isProductLoading={isProductLoading}
810	                isBasketLoading={isBasketLoading}
811	                isWishlistLoading={isWishlistLoading}
812	                validateOrderability={handleChildProductValidation}
813	                childProductOrderability={childProductOrderability}
814	                setSelectedBundleQuantity={setSelectedBundleQuantity}
815	                selectedBundleParentQuantity={selectedBundleQuantity}
816	                pickupInStore={!!pickupInStoreMap[product?.id]}
817	                setPickupInStore={(checked: boolean) => product && handlePickupInStoreChange(product.id, checked)}
818	                onOpenStoreLocator={onOpenStoreLocator}
819	                showDeliveryOptions={storeLocatorEnabled}
820	              />
821	            </Island>
822	
823	            <hr />
824	
825	            {
826	              // Render the child products
827	              product?.childProducts?.map(
828	                ({ product: childProduct, quantity: childQuantity }: { product: SfccProduct; quantity: number }) => (
829	                  <Box key={childProduct.id} data-testid="child-product">
830	                    <ProductView
831	                      // Do not use an arrow function as we are manipulating the functions scope.
832	                      ref={function (this: ProductViewRefScope, ref: ChildProductRef['ref']) {
833	                        // Assign the "set" scope of the ref, this is how we access the internal
834	                        // validation.
835	                        childProductRefs.current[childProduct.id] = {
836	                          ref,
837	                          validateOrderability: this.validateOrderability,
838	                        };
839	                      }}
840	                      product={childProduct}
841	                      isProductPartOfSet={isProductASet}
842	                      isProductPartOfBundle={isProductABundle}
843	                      childOfBundleQuantity={childQuantity}
844	                      selectedBundleParentQuantity={selectedBundleQuantity}
845	                      addToCart={
846	                        isProductASet
847	                          ? (productSelectionValues: ProductSelectionValue[]) => handleAddToCart(productSelectionValues)
848	                          : null
849	                      }
850	                      addToWishlist={isProductASet ? handleAddToWishlist : null}
851	                      onVariantSelected={(product: SfccProduct, variant: SfccVariant, quantity: number) => {
852	                        if (quantity) {
853	                          setChildProductSelection((previousState) => ({
854	                            ...previousState,
855	                            [product.id]: {
856	                              product,
857	                              variant,
858	                              quantity: isProductABundle ? childQuantity : quantity,
859	                            },
860	                          }));
861	                        } else {
862	                          const selections = {
863	                            ...childProductSelection,
864	                          };
865	                          delete selections[product.id];
866	                          setChildProductSelection(selections);
867	                        }
868	                      }}
869	                      isProductLoading={isProductLoading}
870	                      isBasketLoading={isBasketLoading}
871	                      isWishlistLoading={isWishlistLoading}
872	                      setChildProductOrderability={setChildProductOrderability}
873	                      pickupInStore={!!pickupInStoreMap[childProductSelection[childProduct?.id]?.variant?.productId]}
874	                      setPickupInStore={(checked: boolean) =>
875	                        childProduct &&
876	                        handlePickupInStoreChange(childProductSelection[childProduct?.id]?.variant?.productId, checked)
877	                      }
878	                      onOpenStoreLocator={onOpenStoreLocator}
879	                      showDeliveryOptions={storeLocatorEnabled && !isProductABundle}
880	                    />
881	                    <InformationAccordion product={childProduct} />
882	
883	                    <Box display={['none', 'none', 'none', 'block']}>
884	                      <hr />
885	                    </Box>
886	                  </Box>
887	                ),
888	              )
889	            }
890	          </Fragment>
891	        ) : (
892	          <Fragment>
893	            <Island hydrateOn={'visible'}>
894	              <ProductView
895	                product={product}
896	                category={primaryCategory?.parentCategoryTree || []}
897	                renderHeader={(headerProps) => {
898	                  return (
899	                    <StaticProductHeader
900	                      {...headerProps}
901	                      priceData={isPriceStale ? null : variantScopedPriceData ?? headerProps.priceData}
902	                      isPriceLoading={isPriceStale}
903	                    />
904	                  );
905	                }}
906	                renderVariationAttribute={(attr) =>
907	                  attr.id === 'color' ? (
908	                    <ZimmColourSwatchGroup
909	                      label={attr.name ?? ''}
910	                      selectedName={attr.selectedValue?.name}
911	                      selectedValue={attr.selectedValue?.value}
912	                      values={attr.values.map((v) => ({
913	                        value: v.value ?? '',
914	                        name: v.name,
915	                        href: v.href,
916	                        imageUrl: v.image?.disBaseLink || v.image?.link,
917	                      }))}
918	                    />
919	                  ) : undefined
920	                }
921	                addToCart={handleAddToCart}
922	                addToWishlist={handleAddToWishlist}
923	                isProductLoading={isProductLoading}
924	                isBasketLoading={isBasketLoading}
925	                isWishlistLoading={isWishlistLoading}
926	                childProductOrderability={childProductOrderability}
927	                setChildProductOrderability={setChildProductOrderability}
928	                setSelectedBundleQuantity={setSelectedBundleQuantity}
929	                selectedBundleParentQuantity={selectedBundleQuantity}
930	                pickupInStore={!!pickupInStoreMap[product?.id]}
931	                setPickupInStore={(checked: boolean) => product && handlePickupInStoreChange(product.id, checked)}
932	                onOpenStoreLocator={onOpenStoreLocator}
933	                showDeliveryOptions={storeLocatorEnabled}
934	              />
935	              {/*
936	               * The accordions and the meta block deliberately share one `<Box>`, so the pair is a
937	               * single flex item of the outer `<Stack spacing={16}>` rather than two. Chakra spaces
938	               * a Stack with `gap` rather than a child selector, and `<Island>` emits no element of
939	               * its own while `partialHydrationEnabled` is false, so anything left unwrapped in
940	               * here is a direct child taking a 64px push from its neighbour. Sharing one item
941	               * lands that 64px above the pair instead of between them, which leaves
942	               * `ZimmProductMeta`'s recipe owning both 28px hops — the one below the accordions and
943	               * the one between its own two rows. Hence no spacing props on the Box. The molecule
944	               * returns null when it has neither value to show.
945	               */}
946	              <Box>
947	                <InformationAccordion product={product} />
948	                <ZimmProductMeta modelInfo={staticInfo?.modelInfo} styleCode={staticInfo?.styleCode} />
949	              </Box>
950	            </Island>
951	          </Fragment>
952	        )}
953	
954	        {/* Product Recommendations */}
955	        <Stack spacing={16}>
956	          {!isProductASet && (
957	            <Island hydrateOn={'visible'}>
958	              <RecommendedProducts
959	                title={
960	                  <FormattedMessage
961	                    defaultMessage="Complete the Set"
962	                    id="product_detail.recommended_products.title.complete_set"
963	                  />
964	                }
965	                recommender={EINSTEIN_RECOMMENDERS.PDP_COMPLETE_SET}
966	                products={[product]}
967	                mx={{ base: -4, md: -8, lg: 0 }}
968	                shouldFetch={() => product?.id}
969	              />
970	            </Island>
971	          )}
972	          <Island hydrateOn={'visible'}>
973	            <RecommendedProducts
974	              title={
975	                <FormattedMessage
976	                  defaultMessage="You might also like"
977	                  id="product_detail.recommended_products.title.might_also_like"
978	                />
979	              }
980	              recommender={EINSTEIN_RECOMMENDERS.PDP_MIGHT_ALSO_LIKE}
981	              products={[product]}
982	              mx={{ base: -4, md: -8, lg: 0 }}
983	              shouldFetch={() => product?.id}
984	            />
985	          </Island>
986	
987	          <Island hydrateOn={'visible'}>
988	            <RecommendedProducts
989	              // The Recently Viewed recommender doesn't use `products`, so instead we
990	              // provide a key to update the recommendations on navigation.
991	              key={location.key}
992	              title={
993	                <FormattedMessage
994	                  defaultMessage="Recently Viewed"
995	                  id="product_detail.recommended_products.title.recently_viewed"
996	                />
997	              }
998	              recommender={EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED}
999	              mx={{ base: -4, md: -8, lg: 0 }}
1000	            />
1001	          </Island>
1002	        </Stack>
1003	      </Stack>
1004	    </Box>
1005	  );
1006	};
1007	
1008	ProductDetail.getTemplateName = () => 'product-detail';
1009	
1010	/*
1011	 * The base file declares `ProductDetail.propTypes = {match: PropTypes.object}` purely as
1012	 * documentation — the component takes no props and never reads `match`. The TypeScript
1013	 * signature above expresses the same thing at compile time, so the runtime `prop-types`
1014	 * declaration is not carried over.
1015	 */
1016	
1017	export default ProductDetail;
1018

