1	import React, { useEffect, useRef, useState } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { useIntl } from 'react-intl';
4	import { ZimmColourSwatch } from '../../atoms/zimmColourSwatch';
5	import { ZimmIcon } from '../../atoms/zimmIcon';
6	
7	const ZIMM_COLOUR_SWATCH_GROUP_RECIPE = 'ZimmColourSwatchGroup';
8	
9	/**
10	 * Fixed page size once pagination kicks in — Figma's own interaction annotation on this node:
11	 * "Pagination appears if there are more than 4 swatches."
12	 */
13	const SWATCHES_PER_PAGE = 4;
14	
15	/*
16	 * Reused verbatim from base SFCC's own swatch-group/index.jsx, the same way
17	 * zimmProductStyleCode/index.tsx reuses its own base-template label id — so this stays
18	 * consistent with base's i18n key rather than fragmenting translation keys. `values={{label}}`
19	 * interpolates the SFCC attribute display name (e.g. "Colour") passed in as this component's own
20	 * `label` prop.
21	 */
22	const GROUP_LABEL_MESSAGE = {
23	  id: 'swatch_group.selected.label',
24	  defaultMessage: '{label}:',
25	};
26	
27	/*
28	 * Base SFCC's own SwatchGroup has no pagination at all, so these two have no base id to reuse —
29	 * new, Zimmermann-only ids.
30	 */
31	const PREVIOUS_PAGE_MESSAGE = {
32	  id: 'zimm_colour_swatch_group.pagination.previous',
33	  defaultMessage: 'Previous colours',
34	};
35	const NEXT_PAGE_MESSAGE = {
36	  id: 'zimm_colour_swatch_group.pagination.next',
37	  defaultMessage: 'Next colours',
38	};
39	
40	/**
41	 * One selectable colour variation, as the caller (the PDP page) resolves it from SFCC's own
42	 * variation-attribute values.
43	 */
44	export type ZimmColourSwatchValue = {
45	  /** SFCC variation-attribute value, e.g. "BAYBL" — the identity matched against `selectedValue`. */
46	  value: string;
47	  /** Colour display name, e.g. "Bay Blue". Rendered as the dynamic label text and, via the atom, each swatch's accessible name. */
48	  name: string;
49	  /** Destination URL for this colour. Absent for the quick-view-modal path — see ZimmColourSwatch. */
50	  href?: string;
51	  /**
52	   * Fully resolved swatch-fill image URL. Undefined means this colour's index image is not
53	   * populated (AC 5) — such a value is filtered out before rendering and never surfaced to the
54	   * shopper, regardless of any stock/orderability field it might otherwise carry.
55	   */
56	  imageUrl?: string;
57	};
58	
59	/** A colour value that has passed the AC-5 image-populated filter below. */
60	type PopulatedSwatchValue = ZimmColourSwatchValue & { imageUrl: string };
61	
62	type ZimmColourSwatchGroupProps = {
63	  /**
64	   * SFCC attribute display name, e.g. "Colour" — interpolated into the "{label}:" text and used
65	   * as the swatches `radiogroup`'s aria-label.
66	   */
67	  label: string;
68	  /** Display name of the currently selected colour, e.g. "Bay Blue". */
69	  selectedName?: string;
70	  /** SFCC variation-attribute value of the currently selected colour, e.g. "BAYBL". */
71	  selectedValue?: string;
72	  /** Every selectable colour value for this attribute, populated or not — this component performs its own AC-5 filter. */
73	  values: readonly ZimmColourSwatchValue[];
74	};
75	
76	/**
77	 * Molecule — the PDP colour-swatch group: the "Colour: Bay Blue" label row, and — once there is
78	 * more than one populated colour — the row of clickable colour swatches beneath it.
79	 *
80	 * Purely presentational — no data-fetching hook of any kind. SFCC data resolution (building
81	 * `imageUrl`/`href` from a product's variation attributes) happens at the page level, not here.
82	 *
83	 * Three ACs live here as branch logic:
84	 *   - AC 5: a colour whose index image is not populated is filtered out before rendering and
85	 *     never surfaced to the shopper. Content-population, not stock/orderability — the filter
86	 *     keys on `imageUrl` alone.
87	 *   - AC 1: filtering *then* counting means an unpopulated colour never counts toward "there are
88	 *     multiple colours" — one populated colour (or zero) renders the label row only, with no
89	 *     `swatches` node and no `radiogroup` role at all.
90	 *   - Pagination: more than 4 populated colours paginates in fixed 4-wide windows. Paging moves
91	 *     the window only, never the selection — a selected colour that pages out of view stays
92	 *     selected, it is just not visible until paged back into view.
93	 *
94	 * @param props see ZimmColourSwatchGroupProps
95	 */
96	export const ZimmColourSwatchGroup = ({ label, selectedName, selectedValue, values }: ZimmColourSwatchGroupProps) => {
97	  const intl = useIntl();
98	  const swatchesRef = useRef<HTMLDivElement>(null);
99	
100	  // AC 5. Lives here, not at the page level, because this component's own test file is where its
101	  // contract must be provable — the PDP page has no test file of its own. A type predicate
102	  // rather than a `!` at the call site below: TypeScript then knows every entry of `populated`
103	  // genuinely carries a string `imageUrl`, with no unchecked assertion needed.
104	  const populated = values.filter((value): value is PopulatedSwatchValue => Boolean(value.imageUrl));
105	
106	  // The page that actually contains the current selection, recomputed fresh every render from
107	  // `populated`/`selectedValue` — never a second, independently-drifting copy of "where the
108	  // selection is." -1 (no match, or nothing selected yet) falls back to page 1, matching the
109	  // existing no-selection behaviour.
110	  const selectedIndex = populated.findIndex((value) => value.value === selectedValue);
111	  const selectedPageStart =
112	    selectedIndex === -1 ? 0 : Math.floor(selectedIndex / SWATCHES_PER_PAGE) * SWATCHES_PER_PAGE;
113	
114	  // Seeded from `selectedPageStart` so the very first render already lands on the selection's
115	  // real page — React only consumes this argument on mount, so this alone covers first render.
116	  // It is not enough on its own once mounted: if `selectedValue`/`populated` change afterwards,
117	  // this initial value would go stale, because `pageStart` gates which items are even rendered,
118	  // not just which one shows a highlight — unlike base SFCC's own per-render-derived
119	  // `isFocusable`, which only ever affects a highlight on whatever is already on screen. The
120	  // effect below is what keeps `pageStart` correct for the lifetime of an already-mounted
121	  // instance.
122	  const [pageStart, setPageStart] = useState(selectedPageStart);
123	
124	  // Resyncs `pageStart` to the selection's own page whenever `selectedPageStart` itself changes —
125	  // i.e. whenever a `selectedValue`/`populated` prop update moves the selection to a different
126	  // page on an already-mounted instance. Manual prev/next clicks (handlePrevPage/handleNextPage
127	  // below) only ever set `pageStart` directly and never touch `selectedPageStart`, so this effect
128	  // does not re-run on a manual page click and manual paging keeps working exactly as before in
129	  // between selection changes.
130	  useEffect(() => {
131	    setPageStart(selectedPageStart);
132	  }, [selectedPageStart]);
133	
134	  const isPaginated = populated.length > SWATCHES_PER_PAGE;
135	
136	  // Resolved here — once `isPaginated` is known — rather than at the top of this component: the
137	  // recipe needs it up front so the `swatches` part can reserve a fixed page-width footprint once
138	  // paginated, so the whole component doesn't visibly resize between a full page and a shorter
139	  // final page. See zimmColourSwatchGroup.css.ts's own comment on the `swatches` part for the
140	  // layout bug this fixes. Still an unconditional hook call — nothing above this point returns
141	  // early — so this reordering doesn't break the Rules of Hooks.
142	  const styles = useMultiStyleConfig(ZIMM_COLOUR_SWATCH_GROUP_RECIPE, { isPaginated });
143	
144	  // Defensive clamp, not part of any AC: if `values` shrinks while this instance stays mounted
145	  // (no remount), a stale `pageStart` left over from a longer list would otherwise slice to an
146	  // empty window with no swatches rendered at all.
147	  const lastPageStart = Math.max(0, Math.ceil(populated.length / SWATCHES_PER_PAGE) - 1) * SWATCHES_PER_PAGE;
148	  const currentPageStart = Math.min(pageStart, lastPageStart);
149	  const windowed = isPaginated ? populated.slice(currentPageStart, currentPageStart + SWATCHES_PER_PAGE) : populated;
150	  const canGoBack = currentPageStart > 0;
151	  const canGoForward = currentPageStart + SWATCHES_PER_PAGE < populated.length;
152	
153	  const handlePrevPage = () => setPageStart((current) => Math.max(0, current - SWATCHES_PER_PAGE));
154	  const handleNextPage = () => setPageStart((current) => Math.min(current + SWATCHES_PER_PAGE, lastPageStart));
155	
156	  /*
157	   * Roving focus across the *rendered* swatches, mirroring base SFCC's own
158	   * swatch-group/index.jsx onKeyDown (ArrowUp/ArrowLeft = backward, ArrowDown/ArrowRight =
159	   * forward, wrapping at the ends via modulus). Deliberately moves DOM focus only, via
160	   * `.focus()` on the sibling node, rather than touching `isFocusable`/selection state the way
161	   * base's own version does: there is no onVariationChange-equivalent prop here for an arrow
162	   * press to call (product-detail, Step 4, passes none yet), so there is nothing to trigger
163	   * beyond moving which element has focus. Activation stays the anchor's native Enter key,
164	   * inherited for free from the atom's ColourSwatchLink. Space does not activate an anchor
165	   * element — a native browser/HTML behaviour, not a bug, and an inherited parity gap versus a
166	   * true native radio input rather than a new regression introduced here.
167	   */
168	  const handleSwatchesKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
169	    const { key } = event;
170	    if (key !== 'ArrowUp' && key !== 'ArrowDown' && key !== 'ArrowLeft' && key !== 'ArrowRight') return;
171	    event.preventDefault();
172	    const container = swatchesRef.current;
173	    if (!container) return;
174	    const items = Array.from(container.children) as HTMLElement[];
175	    if (items.length === 0) return;
176	    const direction = key === 'ArrowUp' || key === 'ArrowLeft' ? -1 : 1;
177	    const activeIndex = items.indexOf(document.activeElement as HTMLElement);
178	    const fromIndex = activeIndex === -1 ? 0 : activeIndex;
179	    const nextIndex = (fromIndex + direction + items.length) % items.length;
180	    items[nextIndex]?.focus();
181	  };
182	
